thead.append("tr")
    .selectAll("th")
    .data(columns)
    .enter()
    .append("th")
    .text(d => d);
```

### 3. Create Data Rows
```javascript
const rows = tbody.selectAll("tr")
    .data(data)
    .enter()
    .append("tr")
    .attr("id", d => `row-${d.ticker}`);

rows.append("td").text(d => d.ticker);
