// Stock Visualization with D3.js v6

// Global variables
let stockData = [];
let selectedTicker = null;
let simulation;

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return "N/A";
    value = +value;
    if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
    if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
    return value.toFixed(0);
}

// Load and process data
async function loadData() {
    const data = await d3.csv("data/stock-descriptions.csv");

    stockData = data.map(d => ({
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector,
        marketCap: +d.marketCap || 0,
        country: d.country,
        website: d.website,
        isETF: !d.marketCap || d.marketCap === "" || +d.marketCap === 0
    }));

    return stockData;
}

// Create the bubble chart
function createBubbleChart(data) {
    const container = d3.select("#bubble-chart");
    const containerRect = container.node().getBoundingClientRect();
    const width = containerRect.width || 700;
    const height = 620;
    const margin = { top: 20, right: 150, bottom: 20, left: 20 };
    const chartWidth = width - margin.left - margin.right;
    const chartHeight = height - margin.top - margin.bottom;

    // Clear previous
    container.selectAll("*").remove();

    const svg = container.append("svg")
        .attr("width", width)
        .attr("height", height);

    const chartGroup = svg.append("g")
        .attr("transform", `translate(${margin.left}, ${margin.top})`);

    // Get unique sectors
    const sectors = [...new Set(data.map(d => d.sector))];

    // Color scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeTableau10);

    // Radius scale based on market cap
    const maxMarketCap = d3.max(data.filter(d => !d.isETF), d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([8, 50]);

    // ETF default radius
    const etfRadius = 12;

    // Calculate cluster centers for each sector
    const clusterCenters = {};
    const numSectors = sectors.length;
    const clusterRadius = Math.min(chartWidth, chartHeight) * 0.3;

    sectors.forEach((sector, i) => {
        const angle = (2 * Math.PI * i) / numSectors - Math.PI / 2;
        clusterCenters[sector] = {
            x: chartWidth / 2 + Math.cos(angle) * clusterRadius,
            y: chartHeight / 2 + Math.sin(angle) * clusterRadius
        };
    });

    // Create tooltip
    const tooltip = d3.select("body").append("div")
        .attr("class", "tooltip");

    // Get bubble radius
    function getRadius(d) {
        if (d.isETF) return etfRadius;
        return radiusScale(d.marketCap);
    }

    // Create force simulation
    simulation = d3.forceSimulation(data)
        .force("charge", d3.forceManyBody().strength(5))
        .force("center", d3.forceCenter(chartWidth / 2, chartHeight / 2).strength(0.05))
        .force("x", d3.forceX(d => clusterCenters[d.sector].x).strength(0.15))
        .force("y", d3.forceY(d => clusterCenters[d.sector].y).strength(0.15))
        .force("collision", d3.forceCollide().radius(d => getRadius(d) + 2).strength(1))
        .on("tick", ticked);

    // Create bubble groups
    const bubbleGroups = chartGroup.selectAll(".bubble-group")
        .data(data)
        .enter()
        .append("g")
        .attr("class", "bubble-group");

    // Create bubbles
    const bubbles = bubbleGroups.append("circle")
        .attr("class", "bubble")
        .attr("r", d => getRadius(d))
        .attr("fill", d => colorScale(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5)
        .attr("opacity", 0.85)
        .on("mouseover", function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style("visibility", "visible")
                    .html(`
                        <strong>${d.ticker}</strong><br/>
                        <span>${d.name}</span><br/>
                        <span class="sector-badge" style="background-color: ${colorScale(d.sector)}">${d.sector}</span>
                    `);
            }
            d3.select(this)
                .attr("stroke", "#333")
                .attr("stroke-width", 3);
        })
        .on("mousemove", function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style("top", (event.pageY - 10) + "px")
                    .style("left", (event.pageX + 15) + "px");
            }
        })
        .on("mouseout", function(event, d) {
            tooltip.style("visibility", "hidden");
            d3.select(this)
                .attr("stroke", selectedTicker === d.ticker ? "#000" : "#fff")
                .attr("stroke-width", selectedTicker === d.ticker ? 4 : 1.5);
        })
        .on("click", function(event, d) {
            selectStock(d.ticker);
        });

    // Create labels
    const labels = bubbleGroups.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .style("font-size", d => Math.min(getRadius(d) * 0.6, 11) + "px");

    // Tick function
    function ticked() {
        bubbleGroups.attr("transform", d => {
            // Keep bubbles within bounds
            d.x = Math.max(getRadius(d), Math.min(chartWidth - getRadius(d), d.x));
            d.y = Math.max(getRadius(d), Math.min(chartHeight - getRadius(d), d.y));
            return `translate(${d.x}, ${d.y})`;
        });
    }

    // Create legend
    const legend = svg.append("g")
        .attr("class", "legend")
        .attr("transform", `translate(${width - 140}, 30)`);

    // Legend background
    legend.append("rect")
        .attr("x", -10)
        .attr("y", -15)
        .attr("width", 135)
        .attr("height", sectors.length * 22 + 20)
        .attr("fill", "white")
        .attr("stroke", "#ddd")
        .attr("rx", 4);

    // Legend title
    legend.append("text")
        .attr("x", 0)
        .attr("y", 0)
        .style("font-weight", "bold")
        .style("font-size", "12px")
        .text("Sectors");

    // Legend items
    const legendItems = legend.selectAll(".legend-item")
        .data(sectors)
        .enter()
        .append("g")
        .attr("class", "legend-item")
        .attr("transform", (d, i) => `translate(0, ${i * 22 + 15})`);

    legendItems.append("rect")
        .attr("width", 14)
        .attr("height", 14)
        .attr("rx", 2)
        .attr("fill", d => colorScale(d));

    legendItems.append("text")
        .attr("x", 20)
        .attr("y", 11)
        .text(d => d);

    // Store references for selection
    window.bubbles = bubbles;
    window.colorScale = colorScale;
}

// Create data table
function createDataTable(data) {
    const container = d3.select("#data-table");
    container.selectAll("*").remove();

    const table = container.append("table")
        .attr("class", "data-table");

    // Header
