        .attr("stroke", "#000")
        .attr("stroke-width", 4);

    // Highlight table row
    const row = d3.select(`#row-${ticker}`);
    row.classed("highlighted", true);

    // Scroll row into view
    const rowElement = document.getElementById(`row-${ticker}`);
    if (rowElement) {
        rowElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

